const norm = (s) => String(s || '').replace(/[‘’]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase();
const BY_LABEL = new Map(Object.entries(IMAGES).map(([k, v]) => [norm(k), v]));

/** Image for a placeholder label, or null. */
export const siteImageFor = (label) => BY_LABEL.get(norm(label)) || null;
